let filteredProducts = [...products];
let cartCount = 0;

const app = document.createElement("div");
document.body.appendChild(app);

createLayout();
renderProducts(filteredProducts);

function createLayout() {
  const header = document.createElement("div");
  header.className = "header";

  const title = document.createElement("h1");
  title.textContent = "Product Catalog";

  const darkBtn = document.createElement("button");
  darkBtn.textContent = "Dark Mode";

  darkBtn.addEventListener("click", () => {
    document.body.classList.toggle("dark-mode");
  });

  header.append(title, darkBtn);

  const controls = document.createElement("div");
  controls.className = "controls";

  const search = document.createElement("input");
  search.placeholder = "Search product...";

  search.addEventListener("input", (e) => {
    searchProducts(e.target.value);
  });

  const sort = document.createElement("select");

  sort.innerHTML = `
        <option value="">Sort</option>
        <option value="priceAsc">Giá tăng</option>
        <option value="priceDesc">Giá giảm</option>
        <option value="name">Tên A-Z</option>
        <option value="rating">Rating cao nhất</option>
    `;

  sort.addEventListener("change", (e) => {
    sortProducts(e.target.value);
  });

  controls.append(search, sort);
  ["all", "phone", "laptop", "audio", "tablet"].forEach((category) => {
    const btn = document.createElement("button");
    btn.textContent = category;
    btn.addEventListener("click", () => {
      filterByCategory(category);
    });
    controls.appendChild(btn);
  });

  const cart = document.createElement("div");
  cart.className = "cart";
  cart.innerHTML = "🛒";

  const badge = document.createElement("span");
  badge.className = "badge";
  badge.textContent = "0";

  cart.appendChild(badge);

  const productContainer = document.createElement("div");
  productContainer.className = "products";
  productContainer.id = "products";

  app.append(header, controls, cart, productContainer);
}

function renderProducts(list) {
  const container = document.querySelector("#products");
  container.innerHTML = "";
  list.forEach((product) => {
    const card = document.createElement("div");
    card.className = "card";

    const img = document.createElement("img");
    img.src = product.image;

    const body = document.createElement("div");
    body.className = "card-body";

    const name = document.createElement("h3");
    name.textContent = product.name;

    const price = document.createElement("p");
    price.className = "price";
    price.textContent = product.price.toLocaleString() + "đ";

    const rating = document.createElement("p");
    rating.textContent = "⭐ " + product.rating;

    const btn = document.createElement("button");
    btn.textContent = "Thêm giỏ";

    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      cartCount++;
      document.querySelector(".badge").textContent = cartCount;
    });

    card.addEventListener("click", () => {
      showModal(product);
    });

    body.append(name, price, rating, btn);

    card.append(img, body);

    container.appendChild(card);
  });
}

function searchProducts(keyword) {
  filteredProducts = products.filter((product) =>
    product.name.toLowerCase().includes(keyword.toLowerCase()),
  );
  renderProducts(filteredProducts);
}

function filterByCategory(category) {
  if (category === "all") {
    filteredProducts = [...products];
  } else {
    filteredProducts = products.filter(
      (product) => product.category === category,
    );
  }
  renderProducts(filteredProducts);
}

function sortProducts(type) {
  let data = [...filteredProducts];
  if (type === "priceAsc") {
    data.sort((a, b) => a.price - b.price);
  }
  if (type === "priceDesc") {
    data.sort((a, b) => b.price - a.price);
  }
  if (type === "name") {
    data.sort((a, b) => a.name.localeCompare(b.name));
  }
  if (type === "rating") {
    data.sort((a, b) => b.rating - a.rating);
  }
  renderProducts(data);
}

function showModal(product) {
  const modal = document.createElement("div");
  modal.className = "modal";
  const content = document.createElement("div");
  content.className = "modal-content";
  content.innerHTML = `
        <h2>${product.name}</h2>
        <p>Giá:
            ${product.price.toLocaleString()}đ
        </p>
        <p>Category:
            ${product.category}
        </p>
        <p>Rating:
            ${product.rating}
        </p>
    `;

  modal.appendChild(content);
  modal.addEventListener("click", () => {
    modal.remove();
  });

  document.body.appendChild(modal);
}
